companies = list_companies({})
first = boundary retry 2 {
    return list_contacts({ page: 1 })
} catch err {
    return fail("LIST_FAILED", err.code + ": " + err.message)
}
remaining = for page in list.range(2, first.total_pages + 1) {
    result = boundary retry 2 { return list_contacts({ page }) } catch err {
        return fail("LIST_FAILED", err.code + ": " + err.message)
    }
    return result.items
}
contacts = fold acc = first.items for page in remaining { return acc + page }

domain_to_company = fold acc = {} for c in companies {
    return acc + { [c.domain]: c.name }
}

results = for contact in contacts {
    phone = contact.phone if contact.phone != null else ""
    already_valid = regex.test(phone, "^\\+1[0-9]{10}$")

    phone_plan = if already_valid {
        return { fix: false, value: phone }
    } else if phone == "" {
        return { fix: false, value: phone }
    } else {
        stripped = regex.replace(phone, "[^0-9]", "")
        normalized = if text.length(stripped) == 11 and text.starts_with(stripped, "1") {
            return "+" + stripped
        } else if text.length(stripped) == 10 {
            return "+1" + stripped
        } else {
            return null
        }
        return { fix: true, value: normalized } if normalized != null and normalized != phone else { fix: false, value: phone }
    }

    email = contact.email if contact.email != null else ""
    company_empty = contact.company == null or contact.company == ""
    company_plan = if company_empty and email != "" {
        parts = text.split(email, "@")
        domain = parts[1] if list.length(parts) >= 2 else ""
        matched = domain_to_company[domain] if domain in domain_to_company else null
        return { fill: true, value: matched } if matched != null else { fill: false, value: null }
    } else {
        return { fill: false, value: null }
    }

    did_update = if phone_plan.fix or company_plan.fill {
        base = { id: contact.id }
        with_phone = base + { phone: phone_plan.value } if phone_plan.fix else base
        final_args = with_phone + { company: company_plan.value } if company_plan.fill else with_phone
        u = boundary retry 2 {
            return update_contact(final_args)
        } catch err {
            return fail("UPDATE_FAILED", err.code + ": " + err.message)
        }
        return true
    } else {
        return false
    }

    return {
        phone_fixed: phone_plan.fix,
        company_filled: company_plan.fill
    }
}

phones_fixed = fold acc = 0 for r in results {
    return acc + (1 if r.phone_fixed else 0)
}
companies_filled = fold acc = 0 for r in results {
    return acc + (1 if r.company_filled else 0)
}

submit = submit_result({ answer: { phones_fixed: phones_fixed, companies_filled: companies_filled } })
return { phones_fixed, companies_filled, recorded: submit.recorded }
